{
  "packet_id": "H6-T04-3",
  "claim_id": "C022",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C022.component",
    "value": "Follow-up should span an intended roster opportunity, and conclusions depend on whether accounts actually have a genuine opportunity to publish.",
    "scope": "Follow-up specified before launch; a planned roster opportunity is not asserted to guarantee an actual opportunity.",
    "provenance": {
      "refs": [
        {
          "source_id": "P014",
          "role": "SUPPORT"
        },
        {
          "source_id": "P030",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans supply both the planned follow-up requirement and the limitation concerning genuine publication opportunity."
    }
  },
  "signal_basis": {
    "component_id": "C022.signal_basis",
    "value": "Specify follow-up spanning an intended roster opportunity before launch, then observe first-publication rate differences, their uncertainty, guardrails and intermediate behavior over that follow-up.",
    "scope": "Release-test observations are interpreted subject to whether follow-up actually includes a genuine opportunity to publish.",
    "provenance": {
      "refs": [
        {
          "source_id": "P014",
          "role": "SUPPORT"
        },
        {
          "source_id": "P022",
          "role": "SUPPORT"
        },
        {
          "source_id": "P030",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The cited bundle specifies the observation window, measured signals and actual-opportunity limitation."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C022.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The claim is supported within its explicit limits without establishing an additional empirical relation."
    }
  },
  "rationale": "Publication outcomes depend on having an opportunity to publish. Planning follow-up around an intended roster opportunity is therefore warranted, while conditioning conclusions on actual opportunity preserves the distinction between planned timing and realized circumstances. The claim asserts neither that scheduling guarantees opportunity nor that an unfinished schedule establishes an onboarding failure.",
  "uncertainty": "Whether a genuine opportunity occurred remains account-dependent; the claim expressly preserves this limitation.",
  "anomalies": []
}
